graph['A'] = {'B': 2}
graph['B'] = {'C': 3}
graph['C'] = {'D': 4}
graph['D'] = {'A': 5}

dp, prev = shortest_odd_paths(graph)
print("Shortest odd paths:", dp)
print("Path from A to D:", print_path(prev, 0, 3, ['A', 'B', 'C', 'D']))
```

