```javascript
const express = require('express');
const mysql = require('mysql');
const papa = require('papa');
const fs = require('fs');
const { Worker, isMainThread, parentPort } = require('worker_threads');
const nodemailer = require('nodemailer');

// Database configuration
const dbConfig = {
  host: 'localhost',
  user: 'root',
  password: 'password',
  database: 'testdb'
};

// Create MySQL connection
const connection = mysql.createConnection(dbConfig);

// Initialize Express app
const app = express();
app.use(express.json());

// Email configuration
let transporter = nodemailer.createTransport({
  service: 'gmail',
  auth: {
    user: 'your-email@gmail.com',
    pass: 'your-password'
  }
});

// Function to insert customer into database
function insertCustomer(customer) {
  const query = 'INSERT INTO customers (name, email) VALUES (?, ?)';
  connection.query(query, [customer.name, customer.email], (error, results) => {
    if (error) throw error;
  });
}

// Worker thread for CSV processing
if (!isMainThread) {
  const csvFilePath = parentPort.once('message', (data) => {
    const { filePath } = data;
    processCSVStream(filePath);
  });

  function processCSVStream(csvFilePath) {
    const stream = fs.createReadStream(csvFilePath);
    const parser = papa.parse(stream, {
      header: true,
      step: (results, parser) => {
        insertCustomer(results.data[0]);
      },
      complete: () => {
        sendEmail();
        parentPort.postMessage('Processing completed');
      },
      error: (err) => {
        console.error('Error parsing CSV:', err);
        parentPort.postMessage('Error occurred during processing');
      }
    });
  }

  function sendEmail() {
    let mailOptions = {
      from: 'your-email@gmail.com',
      to: 'admin@example.com',
      subject: 'Database Insertion Completed',
      text: 'Customer data insertion completed.'
    };

    transporter.sendMail(mailOptions, function(error, info) {
      if (error) {
        console.log('Error sending email:', error);
      } else {
        console.log('Email sent:', info.response);
      }
    });
  }
} else {
  // API endpoint to trigger CSV processing
  app.post('/process-csv', (req, res) => {
    const worker = new Worker(__filename, {
      workerData: { filePath: req.body.csvFilePath }
    });
    worker.on('message', (msg) => {
      console.log(msg);
      res.send(msg);
    });
    worker.on('error', (err) => {
      console.error(err);
      res.status(500).send('Worker error');
    });
    worker.on('exit', (code) => {
      if (code !== 0)
        console.error(`Worker stopped with exit code ${code}`);
    });
  });

  // Start the server
  app.listen(3000, () => {
    console.log('Server is running on port 3000');
  });
}
```

