    workerData: { filePath: job.data.filePath }
  });
  await new Promise((resolve, reject) => {
    worker.on('message', (msg) => {
      console.log(msg);
      resolve();
    });
    worker.on('error', (err) => {
      reject(err);
    });
    worker.on('exit', (code) => {
      if (code !== 0) {
        reject(new Error(`Worker stopped with exit code ${code}`));
      }
    });
  });
});

app.listen(3000, () => {
