import 'dart:io';
import 'package:image/image.dart' as img;

// Function to split an image into four parts from the center
List<List<int>> splitImageIntoFourParts(String imagePath) {
  try {
    // Load the image file
    List<int> imageData = File(imagePath).readAsBytesSync();
    img.Image image = img.decodeImage(imageData)!;

    // Calculate dimensions for splitting
    int halfWidth = image.width ~/ 2;
    int halfHeight = image.height ~/ 2;

    // Create four new images from the original one
    img.Image topLeft = img.copyCrop(image, 0, 0, halfWidth, halfHeight);
    img.Image topRight = img.copyCrop(image, halfWidth, 0, halfWidth, halfHeight);
    img.Image bottomLeft = img.copyCrop(image, 0, halfHeight, halfWidth, halfHeight);
    img.Image bottomRight = img.copyCrop(image, halfWidth, halfHeight, halfWidth, halfHeight);

    // Encode each part to PNG and return as a list of byte arrays
    return [
      img.encodePng(topLeft),
      img.encodePng(topRight),
      img.encodePng(bottomLeft),
      img.encodePng(bottomRight),
    ];
  } catch (e) {
    throw Exception("Failed to process image: $e");
  }
}

void main() {
