// Importing Three.js library
import * as THREE from 'three';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls.js';

function init() {
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer();
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    // Adding an axis helper to the scene
    const axesHelper = new THREE.AxesHelper(5);
    scene.add(axesHelper);

    // Define the function to plot (example: a hyperbolic paraboloid)
    const func = (x, y) => y * y - x * x;

    // Generate vertices and faces for the mesh
    const step = 0.1;
    const geometry = new THREE.Geometry();
    for (let x = -1; x <= 1; x += step) {
        for (let y = -1; y <= 1; y += step) {
            const z = func(x, y);
            geometry.vertices.push(new THREE.Vector3(x, y, z));
        }
    }

    // Add faces to the geometry (simplified for demonstration)
    for (let i = 0; i < geometry.vertices.length - 1; i++) {
        if ((i + 1) % (1 / step) !== 0) {
            const face = new THREE.Face3(i, i + 1, i + (1 / step));
            geometry.faces.push(face);
        }
    }

    const material = new THREE.MeshBasicMaterial({ color: 0x00ff00, wireframe: true });
    const mesh = new THREE.Mesh(geometry, material);
    scene.add(mesh);

    camera.position.z = 5;

    const controls = new OrbitControls(camera, renderer.domElement);

    function animate() {
        requestAnimationFrame(animate);
        renderer.render(scene, camera);
    }

    animate();
}

init();
