```python
import numpy as np
import matplotlib.pyplot as plt
from mpl_toolkits.mplot3d import Axes3D
from mpl_toolkits.mplot3d.art3d import Poly3DCollection

# Step 1: Generate input values for x and y
x_values = np.arange(-1, 1.1, 0.1)  # Increment of 0.1, including 1
y_values = np.arange(-1, 1.1, 0.1)

# Create a meshgrid for x and y values
X, Y = np.meshgrid(x_values, y_values)

# Step 2: Choose and apply the function to calculate z values
# Example: Hyperbolic Paraboloid
Z = X**2 - Y**2  # Change this line to plot a different function

# Step 3: Plotting
fig = plt.figure()
ax = fig.add_subplot(111, projection='3d')

# Plot the surface
surf = ax.plot_surface(X, Y, Z, cmap='viridis', linewidth=0, antialiased=False)

# Add a plane at z=0 for reference
plane = ax.plot_surface(X, Y, np.zeros_like(Z), alpha=0.2, color='gray', linewidth=0, antialiased=False)

# Customize the axes
ax.set_xlabel('X axis')
ax.set_ylabel('Y axis')
ax.set_zlabel('Z axis')

# Adding an axis helper manually (matplotlib doesn't have a built-in axis helper)
ax.quiver(0, 0, 0, 1, 0, 0, length=1, normalize=True, color='r')  # X-axis
ax.quiver(0, 0, 0, 0, 1, 0, length=1, normalize=True, color='g')  # Y-axis
ax.quiver(0, 0, 0, 0, 0, 1, length=1, normalize=True, color='b')  # Z-axis

# Mouse controls for rotation and scaling
def on_rotate(event):
    if event.button == 'up':
        ax.view_init(elev=ax.elev + 1, azim=ax.azim)
    elif event.button == 'down':
        ax.view_init(elev=ax.elev - 1, azim=ax.azim)
    elif event.button == 'left':
        ax.view_init(elev=ax.elev, azim=ax.azim + 1)
    elif event.button == 'right':
        ax.view_init(elev=ax.elev, azim=ax.azim - 1)
    fig.canvas.draw_idle()

def on_zoom(event):
    if event.button == 'scroll_up':
        ax.dist -= 1
    elif event.button == 'scroll_down':
        ax.dist += 1
    fig.canvas.draw_idle()

fig.canvas.mpl_connect('scroll_event', on_zoom)
fig.canvas.mpl_connect('button_press_event', on_rotate)

plt.show()
```

### Explanation:
- **Mouse Controls**: We've added functions `on_rotate` and `on_zoom` to handle mouse button presses and scroll events. These functions adjust the elevation (`elev`) and azimuth (`azim`) angles for rotation and the distance (`dist`) for zooming.
- **Axis Helper**: Manually added arrows representing the X, Y, and Z axes using `quiver`.

