function init() {
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer();
    renderer.setSize(window.innerWidth, window.innerHeight);
    document.body.appendChild(renderer.domElement);

    // Adding an axis helper to the scene
    const axesHelper = new THREE.AxesHelper(5);
    scene.add(axesHelper);

    // Define the function to plot
    const func = (u, v) => {
        return new THREE.Vector3(u, v, Math.sqrt(u * u + v * v)); // Example function: Cone shape
    };

    // Use ParametricGeometry to generate the mesh
    const geometry = new THREE.ParametricGeometry(func, 100, 100);

    const material = new THREE.MeshBasicMaterial({ color: 0x00ff00, wireframe: true });
    const mesh = new THREE.Mesh(geometry, material);
    scene.add(mesh);

    camera.position.z = 5;

    const controls = new OrbitControls(camera, renderer.domElement);

    function animate() {
        requestAnimationFrame(animate);
        renderer.render(scene, camera);
    }

    animate();
}

init();
