    % Compare with experimental or analytical results
    relErrCp = abs(cp - expCp) ./ expCp;
    relErrCl = abs(cl - expCl) / expCl;

    disp('Relative Error in Pressure Coefficients:');
    disp(relErrCp);
    disp(['Relative Error in Lift Coefficient: ', num2str(relErrCl)]);

    % Check accuracy for different panel numbers (example)
