#### Flask Backend Code

```python
from flask import Flask, request, jsonify
import os
from werkzeug.utils import secure_filename
import sqlite3

app = Flask(__name__)

# Database setup
def init_db():
    conn = sqlite3.connect('photos.db')
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS photos
                 (id INTEGER PRIMARY KEY, name TEXT UNIQUE, price REAL, description TEXT, filename TEXT)''')
    c.execute('''CREATE TABLE IF NOT EXISTS duplicates
                 (id INTEGER PRIMARY KEY, original_name TEXT, price REAL, description TEXT, filename TEXT)''')
    conn.commit()
    conn.close()

@app.route('/upload', methods=['POST'])
def upload_file():
    if 'file' not in request.files:
        return "No file part", 400
    file = request.files['file']
    if file.filename == '':
        return "No selected file", 400
    if file:
        filename = secure_filename(file.filename)
        file.save(os.path.join("uploads/", filename))

        # Extract other form data
        name = request.form.get('name')
        price = float(request.form.get('price'))
        description = request.form.get('description')

        # Check for duplicate names
        conn = sqlite3.connect('photos.db')
        c = conn.cursor()
        try:
            c.execute("INSERT INTO photos (name, price, description, filename) VALUES (?, ?, ?, ?)",
                      (name, price, description, filename))
            conn.commit()
            return "File uploaded successfully", 200
        except sqlite3.IntegrityError:
            # Store duplicate photo in duplicates table
            c.execute("INSERT INTO duplicates (original_name, price, description, filename) VALUES (?, ?, ?, ?)",
                      (name, price, description, filename))
            conn.commit()
            return f"Duplicate name {name}, please contact admin to resolve.", 409
        finally:
            conn.close()

@app.route('/admin/resolve_duplicate', methods=['POST'])
def resolve_duplicate():
    original_name = request.form.get('original_name')
    action = request.form.get('action')  # 'keep' or 'delete'
    conn = sqlite3.connect('photos.db')
    c = conn.cursor()
    c.execute("SELECT * FROM duplicates WHERE original_name=?", (original_name,))
    duplicates = c.fetchall()

    if duplicates:
        for duplicate in duplicates:
            if action == 'keep':
                c.execute("INSERT INTO photos (name, price, description, filename) VALUES (?, ?, ?, ?)",
                          (duplicate[1], duplicate[2], duplicate[3], duplicate[4]))
            # Delete the duplicate from the duplicates table
            c.execute("DELETE FROM duplicates WHERE id=?", (duplicate[0],))
    conn.commit()
    conn.close()
    return "Resolved", 200

@app.route('/search', methods=['GET'])
def search_photos():
    query = request.args.get('query', '')
    conn = sqlite3.connect('photos.db')
    c = conn.cursor()
    c.execute("SELECT * FROM photos WHERE name LIKE ? OR description LIKE ?", ('%' + query + '%', '%' + query + '%'))
    results = c.fetchall()
    conn.close()

    # Format results for JSON response
    formatted_results = [{"name": r[1], "price": r[2], "description": r[3], "filename": r[4]} for r in results]
