  final TextEditingController _bodyTypeController = TextEditingController();
  XFile? _pickedImage;
  final GlobalKey<FormState> _formKey = GlobalKey<FormState>();

  Future<void> _pickImage() async {
    final picker = ImagePicker();
    final XFile? image = await picker.pickImage(source: ImageSource.gallery);
    setState(() {
      _pickedImage = image;
    });
  }

  Future<String?> _uploadImage(XFile? image) async {
    if (image == null) return null;

    final Reference storageRef = FirebaseStorage.instance.ref().child('profile_pictures/${FirebaseAuth.instance.currentUser!.uid}');
    final UploadTask uploadTask = storageRef.putFile(File(image.path));
    final TaskSnapshot downloadUrl = (await uploadTask.whenComplete(() {}));
    return await downloadUrl.ref.getDownloadURL();
  }

  Future<void> _saveProfileDetails() async {
    final int weight = int.parse(_weightController.text.trim());
    final double height = double.parse(_heightController.text.trim());
    final String bodyType = _bodyTypeController.text.trim();
    final User? user = FirebaseAuth.instance.currentUser;
    if (user != null) {
      final String? profilePicUrl = await _uploadImage(_pickedImage);
      await FirebaseFirestore.instance.collection('users').doc(user.uid).update({
        'weight': weight,
        'height': height,
        'bodyType': bodyType,
        'profilePic': profilePicUrl,
